let __v_1190 = { let __v_1191 = frame.load(rt, "UNDER_RIPE")?; let __v_1192 = pyrt::literals::decode("{\"$tuple\":[\"ripe\",\"riper\",\"ripen\",\"ripens\",\"ripening\",\"unripe\",\"underripe\",\"overripe\",\"hard\",\"firm\",\"still hard\",\"ready\",\"ready to eat\",\"soft enough\",\"tell if\",\"know if\",\"how do i tell\",\"how can i tell\",\"when is it ready\",\"sweet enough\",\"softer\",\"soften\",\"sour\",\"not ripe\",\"too hard\",\"rock hard\",\"tasteless\",\"soft\",\"squishy\",\"soft at the bottom\",\"soft on the bottom\",\"gone soft\",\"getting soft\",\"pick a good\",\"pick good\",\"picking a good\",\"pick the best\",\"pick a ripe\",\"pick ripe\",\"choose a good\",\"choosing a good\",\"choose the best\",\"choose a ripe\",\"choosing a ripe\",\"good one\",\"good ones\",\"best one\",\"how do i pick\",\"how do i choose\",\"how to pick\",\"how to choose\",\"which one to pick\",\"which one to choose\",\"which to pick\",\"which to choose\",\"pick one\",\"choose one\"]}")?; pyrt::ops::add(&__v_1191, &__v_1192)? };
